function w({registerIndicator:b,sourceValues:h,nulls:p}){const d=(o,e)=>{const n=o.length,s=new Array(n).fill(NaN),c=new Array(e).fill(NaN);let t=0,i=0,r=0,u=0,m=0;for(let l=0;l<n;l++){const f=c[t],a=Number.isFinite(o[l])?o[l]:0;if(Number.isFinite(f)){const y=i;i-=f,i+=a,r=r-y+e*a}else u+=1,i+=a,r=r+u*a,m=u*(u+1)*.5;c[t]=a,t=(t+1)%e,s[l]=m>0?r/m:NaN}return s};b({id:"oa-dwma",name:"Double Weighted Moving Average (DWMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1,tooltip:"Lookback for both weighted smoothing passes."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"dwma",type:"line",title:"DWMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,e){const n=Math.max(1,Math.floor(Number(e.period)||10)),s=h(o,e.source||"close"),c=d(s,n),t=d(c,n);return{dwma:p(t)}}})}export{w as default};
